def transform(grid):
    h, w = len(grid), len(grid[0])
    border = grid[0][0]

    # The left panel is the initial run of border-colored cells on the top row.
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == border:
        panel_w += 1
    panel = [row[:panel_w] for row in grid]

    # Find the colored objects on the right and record their row-count profiles.
    colors = sorted({v for row in grid for v in row
                     if v not in (0, border)})
    objects = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(panel_w, w)
                 if grid[r][c] == color]
        if not cells:
            continue
        lo, hi = min(r for r, c in cells), max(r for r, c in cells)
        profile = tuple(sum(grid[r][c] == color for c in range(panel_w, w))
                        for r in range(lo, hi + 1))
        objects.append((color, profile))

    # Each chamber is the rows between full-width border-colored separators.
    chambers = []
    r = 0
    while r < h:
        if all(panel[r][c] == border for c in range(panel_w)):
            start = r + 1
            end = start
            while end < h and not all(panel[end][c] == border
                                      for c in range(panel_w)):
                end += 1
            if start < end:
                profile = tuple(sum(panel[rr][c] == 0
                                    for c in range(1, panel_w - 1))
                                for rr in range(start, end))
                chambers.append((start, end, profile))
            r = end
        else:
            r += 1

    # Match objects to chambers by their row-count profiles; ties follow
    # the objects' color order.
    import itertools
    n = min(len(chambers), len(objects))
    best = None
    best_perm = None
    for perm in itertools.permutations(range(len(objects)), n):
        score = 0
        for i, j in enumerate(perm):
            a, b = chambers[i][2], objects[j][1]
            score += sum(x == y for x, y in zip(a, b))
            score -= abs(len(a) - len(b))
        if best is None or score > best:
            best, best_perm = score, perm

    for i, j in enumerate(best_perm or ()):
        start, end, _ = chambers[i]
        color = objects[j][0]
        for rr in range(start, end):
            for c in range(1, panel_w - 1):
                if panel[rr][c] == 0:
                    panel[rr][c] = color

    return panel
